//! The gold cells (`lab/cells/gold-*.toml`, generated by `fv-lab gold cells
//! --write`, docs/adr/0023-lab-report-and-ci-bridge.md §3) as the serve
//! engine sees them. Each cell runs `fv-gpucheck [--techniques <profile>]
//! engine --model <variant>`; fv-gpucheck installs `<profile>` (none without
//! the flag) at start-up, before it builds the engine, and a profile is
//! installed once per process. `CudaBackend::new` then computes its model's
//! [`ProcessPlan`] and refuses the process when the installed settings differ
//! ([`ProcessPlan::check_installed`]). This runs that same plan and check for
//! every gold cell on the CPU, so a cell that starts without its variant's
//! profile fails here instead of on the GPU (the gold smoke run on
//! `sha-f93a961` failed `h3-larry-turbo` and `sol-h3` that way at once).

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use fastvideo_engine_service::cuda::caps::profile_settings;
use fastvideo_engine_service::cuda::{catalog, find, CudaModel, ProcessPlan, WeightLayout};
use fastvideo_manifest::family::load_dir;

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// `(cell name, argv)` of every arm of every committed gold cell, by name.
fn gold_arms() -> Vec<(String, Vec<String>)> {
    let mut out = Vec::new();
    let dir = repo_root().join("lab/cells");
    for e in std::fs::read_dir(&dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display())) {
        let p = e.expect("entry").path();
        let Some(stem) = p.file_stem().and_then(|s| s.to_str()) else {
            continue;
        };
        if !stem.starts_with("gold-") || p.extension().and_then(|x| x.to_str()) != Some("toml") {
            continue;
        }
        let text = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
        let cell: toml::Table =
            toml::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
        let arms = cell
            .get("arm")
            .and_then(toml::Value::as_array)
            .unwrap_or_else(|| panic!("{stem}: no [[arm]]"));
        for arm in arms {
            let argv = arm
                .get("argv")
                .and_then(toml::Value::as_array)
                .unwrap_or_else(|| panic!("{stem}: an arm with no argv"))
                .iter()
                .map(|a| {
                    a.as_str()
                        .unwrap_or_else(|| panic!("{stem}: argv entry {a}"))
                        .to_owned()
                })
                .collect();
            out.push((stem.to_owned(), argv));
        }
    }
    out.sort();
    out
}

/// Every value of `--name` in `args` (`--name v` or `--name=v`).
fn flag_values<'a>(args: &'a [String], name: &str) -> Vec<&'a str> {
    let eq = format!("{name}=");
    let mut out = Vec::new();
    let mut it = args.iter();
    while let Some(a) = it.next() {
        if a == name {
            out.push(it.next().map(String::as_str).unwrap_or(""));
        } else if let Some(v) = a.strip_prefix(&eq) {
            out.push(v);
        }
    }
    out
}

/// The load-time settings fv-gpucheck installs for `--techniques <profile>`
/// (none without it), as the engine compares them.
fn installed_by(profile: Option<&str>) -> BTreeMap<String, String> {
    profile_settings(profile)
        .unwrap_or_else(|e| panic!("{e}"))
        .iter()
        .map(|(k, v, _)| (k.to_owned(), v.to_owned()))
        .collect()
}

/// The plan `fv-gpucheck engine --model <model>` builds its backend with: the
/// one catalog model `find` resolves, alone in the process.
fn plan_of(cat: &[CudaModel], model: &str) -> ProcessPlan {
    let m = find(cat, model).unwrap_or_else(|| panic!("unknown model {model}"));
    ProcessPlan::for_models(std::slice::from_ref(&m)).unwrap_or_else(|e| panic!("{model}: {e}"))
}

#[test]
fn every_gold_cell_starts_with_the_profile_its_engine_installs() {
    let arms = gold_arms();
    let golds = std::fs::read_dir(repo_root().join("lab/gold"))
        .expect("lab/gold")
        .filter(|e| {
            e.as_ref()
                .is_ok_and(|e| e.path().extension().and_then(|x| x.to_str()) == Some("toml"))
        })
        .count();
    assert_eq!(arms.len(), golds, "one arm per gold file");
    let cat = catalog(&WeightLayout::default()).expect("catalog");
    let mut profiled = 0;
    for (cell, argv) in &arms {
        let engine = argv
            .iter()
            .position(|a| a == "engine")
            .unwrap_or_else(|| panic!("{cell}: no engine subcommand: {argv:?}"));
        let techniques = flag_values(argv, "--techniques");
        assert!(
            techniques.len() <= 1,
            "{cell}: --techniques twice: {argv:?}"
        );
        let techniques = techniques.first().copied();
        let models = flag_values(&argv[engine..], "--model");
        let [model] = models.as_slice() else {
            panic!("{cell}: one --model after engine: {argv:?}");
        };
        let plan = plan_of(&cat, model);
        plan.check_installed(techniques.map(Path::new), &installed_by(techniques))
            .unwrap_or_else(|e| panic!("{cell}: {e}"));
        assert_eq!(
            techniques,
            plan.profile.as_deref(),
            "{cell}: --techniques is the model's own profile"
        );
        profiled += usize::from(plan.profile.is_some());
    }
    assert!(profiled > 0);
}

/// The failure the smoke run hit, on the CPU: the cell as it was generated
/// before the fix (no `--techniques`) is refused with the run's message, and
/// the model's own profile is accepted.
#[test]
fn a_profiled_variant_started_without_its_profile_is_refused() {
    let cat = catalog(&WeightLayout::default()).expect("catalog");
    for (model, profile) in [
        ("h3-larry-turbo", "h3/larry_turbo_dense"),
        ("sol-h3", "h3/sol_h3_4step_engine_ladder"),
    ] {
        let plan = plan_of(&cat, model);
        assert_eq!(plan.profile.as_deref(), Some(profile), "{model}");
        let e = plan
            .check_installed(None, &installed_by(None))
            .expect_err(model);
        assert!(
            e.starts_with("technique settings already installed (None: {}) differ from what the served models need"),
            "{model}: {e}"
        );
        plan.check_installed(Some(Path::new(profile)), &installed_by(Some(profile)))
            .unwrap_or_else(|e| panic!("{model}: {e}"));
    }
    // A variant with no profile runs in a process started with none.
    let plan = plan_of(&cat, "vdn-h3");
    assert_eq!(plan.profile, None);
    plan.check_installed(None, &installed_by(None))
        .expect("vdn-h3 with none");
}

/// Every served variant: the family file's `engine.profile` (what
/// `fv-lab gold cells` passes as `--techniques`, `goldcell::technique_profile`)
/// is the profile the engine's process plan installs for that variant alone.
#[test]
fn every_variant_engine_profile_is_its_process_plan_profile() {
    let set = load_dir(&repo_root().join("families")).expect("families/");
    let cat = catalog(&WeightLayout::default()).expect("catalog");
    let mut n = 0;
    for f in set.families() {
        for v in &f.variants {
            let want = v.engine.get("profile").map(|p| {
                p.as_str()
                    .unwrap_or_else(|| panic!("{}: engine.profile {p}", v.id))
            });
            assert_eq!(plan_of(&cat, &v.id).profile.as_deref(), want, "{}", v.id);
            n += 1;
        }
    }
    assert_eq!(n, cat.len());
}
